    41  static inline Elf_Kind
    42  __attribute__ ((unused))
    43  determine_kind (void *buf, size_t len)
    44  {
    45    /* First test for an archive.  */
    46    if (len >= SARMAG && memcmp (buf, ARMAG, SARMAG) == 0)
    47      return ELF_K_AR;
    48
    49    /* Next try ELF files.  */
    50    if (len >= EI_NIDENT && memcmp (buf, ELFMAG, SELFMAG) == 0)
    51      {
    52        /* Could be an ELF file.  */
    53        int eclass = (int) ((unsigned char *) buf)[EI_CLASS];
    54        int data = (int) ((unsigned char *) buf)[EI_DATA];
    55        int version = (int) ((unsigned char *) buf)[EI_VERSION];
    56
    57        if (eclass > ELFCLASSNONE && eclass < ELFCLASSNUM
    58            && data > ELFDATANONE && data < ELFDATANUM
    59            && version == EV_CURRENT)
    60          return ELF_K_ELF;
    61      }
    62
    63    /* We do not know this file type.  */
    64    return ELF_K_NONE;
    65  }
